# ---------------------------------------------------------------------------
# Provided — keep this. A fake transport for tests, and the driver the tests call:
#   exercise(image_hex, fail, options) flashes bytes.fromhex(image_hex) through a FakeTransport and
#   reports the outcome (other exceptions by type name only), every transport call in order,
#   and every sleep your Flasher asked for.
#   fail maps an operation to the call numbers (1-based, counted across attempts) that misbehave:
#     "connect"/"write": raise TransportError;  "verify": return a wrong digest;
#     "write_bug": raise RuntimeError (a bug, not a transient failure).
# ---------------------------------------------------------------------------
import hashlib
from collections import Counter
from typing import Any, Dict, List


class FakeTransport:
    def __init__(self, fail: Dict[str, List[int]]):
        self.fail = fail
        self.calls: List[str] = []
        self.counts = Counter()
        self.data = bytearray()

    def _tick(self, op: str, label: str) -> int:
        self.counts[op] += 1
        self.calls.append(label)
        return self.counts[op]

    def connect(self):
        n = self._tick("connect", "connect")
        if n in self.fail.get("connect", []):
            raise TransportError(f"connect #{n} failed")
        self.data = bytearray()

    def write(self, chunk: bytes):
        n = self._tick("write", f"write:{len(chunk)}")
        if n in self.fail.get("write_bug", []):
            raise RuntimeError(f"driver bug on write #{n}")
        if n in self.fail.get("write", []):
            raise TransportError(f"write #{n} failed")
        self.data += chunk

    def verify(self) -> str:
        n = self._tick("verify", "verify")
        if n in self.fail.get("verify", []):
            return "0" * 64
        return hashlib.sha256(bytes(self.data)).hexdigest()

    def close(self):
        self.calls.append("close")


def exercise(image_hex: str, fail: Dict[str, List[int]], options: Dict[str, Any]) -> Dict[str, Any]:
    transport, sleeps = FakeTransport(fail), []
    try:
        flasher = Flasher(transport, sleep=sleeps.append, **options)
        outcome = f"ok after {flasher.flash(bytes.fromhex(image_hex))}"
    except FlashError as err:
        cause = type(err.__cause__).__name__ if err.__cause__ else None
        outcome = f"FlashError: {err} (cause: {cause})"
    except Exception as err:
        outcome = type(err).__name__
    return {"outcome": outcome, "calls": transport.calls, "sleeps": sleeps}
